import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';

test(covers(['method:Task.complete', 'criterion:0001/conclusao'], 'Task.complete conclui tarefa e bloqueia repeticao'), () => {
  const task = Task.create('t1', 'pagar contas');
  task.pullEvents();
  task.complete();
  expect(task.status).toBe('completed');
  const events = task.pullEvents();
  expect(events).toHaveLength(1);
  expect(events[0]).toBeInstanceOf(TaskCompleted);
  expect((events[0] as TaskCompleted).payload).toEqual({ taskId: 't1' });
  const act = () => task.complete();
  expect(act).toThrow(DomainError);
  try {
    act();
  } catch (error) {
    expect(error).toBeInstanceOf(DomainError);
    expect((error as DomainError).code).toBe('TASK_ALREADY_COMPLETED');
    return;
  }
  throw new Error('expected Task.complete to throw');
});
